"use client";

import { Button } from "@/components/ui/button";
import { useMemo, useRef, useState, type ReactNode } from "react";
import {
  DataGridBody,
  DataGridHeader,
  DataGridProvider,
  DataGridRoot,
  defineColumns,
  type CellClickCtx,
  type DataGridApi,
  type GridCommand,
} from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 150, flex: 2 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 180, flex: 2 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 100, flex: 1 },
  { id: "active", header: "Active", accessorKey: "active", type: "checkbox", width: 70, flex: 1 },
] as const);

export default function DataGridDetailPanelDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(30), []);
  const rowsById = useMemo(() => new Map(rows.map((row) => [row.id, row])), [rows]);
  const [open, setOpen] = useState(false);
  const [rowId, setRowId] = useState<string | null>(null);
  const gridRef = useRef<DataGridApi<DemoRow> | null>(null);
  const row = rowId === null ? undefined : rowsById.get(rowId);

  const close = () => {
    setOpen(false);
    gridRef.current?.focus();
  };

  const commands = useMemo<Record<string, GridCommand<DemoRow>>>(
    () => ({
      openRow: {
        label: "Open row",
        keys: ["shift+Enter"],
        when: (ctx) => ctx.row !== undefined,
        run: () => setOpen(true),
      },
    }),
    [],
  );

  const openFromClick = (ctx: CellClickCtx<DemoRow, unknown>) => {
    if (ctx.columnId !== "active") setOpen(true);
  };

  return (
    <div className="flex flex-col gap-2">
      <p className="m-0 text-sm text-muted-foreground">
        Click a cell, or press Shift+Enter on the active cell, to show its row. The panel follows the active
        cell while you move with the arrow keys. Escape closes it when focus is inside the panel.
      </p>
      <div className="relative overflow-hidden">
        <DataGridProvider
          ref={gridRef}
          defaultData={rows}
          columns={columns}
          onCellClick={openFromClick}
          onActiveCellChange={(next) => setRowId(next?.rowId ?? null)}
          commands={commands}
        >
          <DataGridRoot className="h-[360px]">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
        <aside
          role="complementary"
          aria-label="Row details"
          inert={!open}
          data-open={open}
          onKeyDown={(event) => {
            if (event.key === "Escape") close();
          }}
          className="absolute inset-y-0 end-0 flex w-64 flex-col gap-3 border-s bg-background p-4 shadow-md transition-transform duration-200 motion-reduce:transition-none data-[open=false]:translate-x-full rtl:data-[open=false]:-translate-x-full"
        >
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <h3 className="m-0 truncate text-sm font-semibold">{row?.name ?? "No row"}</h3>
              <p className="m-0 truncate text-xs text-muted-foreground">{row?.email}</p>
            </div>
            <Button type="button" variant="ghost" size="icon-xs" onClick={close} aria-label="Close details">
              ×
            </Button>
          </div>
          {row ? (
            <dl className="m-0 grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-sm">
              <dt className="text-muted-foreground">Role</dt>
              <dd className="m-0">{row.role}</dd>
              <dt className="text-muted-foreground">Age</dt>
              <dd className="m-0">{row.age}</dd>
              <dt className="text-muted-foreground">Joined</dt>
              <dd className="m-0">{row.joined}</dd>
            </dl>
          ) : (
            <p className="m-0 text-sm text-muted-foreground">Select a cell to see its row.</p>
          )}
        </aside>
      </div>
      <Button type="button" variant="outline" size="sm" onClick={() => (open ? close() : setOpen(true))} aria-expanded={open} className="self-start">
        Details
      </Button>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
